(1101, 1, '<summit-registration-20260620@ims.example>', 'International Marketing Summit registration confirmed', 'registration@ims.example', '["zhang.ming@company.com"]', '[]', '[]', '2026-06-20T11:00:00+09:00', 'Registration is confirmed for July 20–22 at Roppongi Conference Center. The detailed session agenda will be published separately.', NULL, 1, 1, 1, NULL, NULL, '{"category":"conference"}', 6101, 146, '2026-06-20T11:00:00+09:00'),
(1127, 1, '<travel-policy-20260622@company.com>', 'Business travel insurance and expense evidence', 'travel@company.com', '["zhang.ming@company.com"]', '[]', '[]', '2026-06-22T09:00:00+08:00', 'International business travel requires the company travel policy or an approved equivalent. Personal accident insurance does not automatically replace trip cancellation, medical evacuation, delay, or baggage coverage. Use actual booking and settlement evidence for reimbursement.', NULL, 1, 1, 1, NULL, NULL, '{"category":"policy"}', 6127, 251, '2026-06-22T09:00:00+08:00'),
(1144, 1, '<tokyo-approval-pending-20260626@company.com>', 'Tokyo trip approval pending', 'manager@company.com', '["zhang.ming@company.com"]', '["travel@company.com"]', '[]', '2026-06-26T16:00:00+08:00', 'The Tokyo business purpose is accepted, but final ticket and hotel authorization remains pending. Reversible holds may be considered only after live terms are checked.', NULL, 1, 1, 0, NULL, NULL, '{"category":"approval"}', 6144, 181, '2026-06-26T16:00:00+08:00'),
