(1226, 1, '<team-handoff-20260628@company.com>', 'Client handoff before Tokyo', 'sales-ops@company.com', '["zhang.ming@company.com"]', '[]', '[]', '2026-06-28T13:20:00+08:00', 'Please complete the Alpha and Borealis account handoffs by July 14. Keep escalation contacts and the post-travel debrief hold visible to the regional team.', NULL, 1, 0, 0, NULL, NULL, '{"category":"work"}', 6226, 155, '2026-06-28T13:20:00+08:00'),
