(1275, 1, '<expense-fields-20260630@company.com>', 'Expense report evidence fields', 'finance@company.com', '["zhang.ming@company.com"]', '[]', '[]', '2026-06-30T14:00:00+08:00', 'Each reimbursement line needs category, amount, currency, settlement status, business purpose, and an available invoice, booking, or bank reference. Save external email as a draft until the evidence is reviewed.', NULL, 0, 1, 0, NULL, NULL, '{"category":"finance"}', 6275, 190, '2026-06-30T14:00:00+08:00'),
