(1329, 1, '<travel-advance-20260701@company.com>', 'Travel advance posted', 'finance@company.com', '["zhang.ming@company.com"]', '[]', '[]', '2026-07-01T08:12:00+08:00', 'A preliminary CNY 2,750 business-travel advance posted to the registered checking account. Reconcile it against final reimbursable costs rather than treating it as income.', NULL, 0, 1, 1, NULL, NULL, '{"category":"finance"}', 6329, 161, '2026-07-01T08:12:00+08:00'),
