(1479, 1, '<roppongi-venue-access-20260624@ims.example>', 'Roppongi venue access and badge desk', 'operations@ims.example', '["zhang.ming@company.com"]', '[]', '[]', '2026-06-24T13:42:00+09:00', 'Badge collection opens at 08:15 on conference days. The venue does not arrange airport transfers, so attendees should verify current public transport independently.', NULL, 1, 0, 0, NULL, NULL, '{"category":"conference"}', 6479, 155, '2026-06-24T13:42:00+09:00'),
(1508, 1, '<summit-agenda-pending-20260630@ims.example>', 'Detailed summit agenda still pending', 'program@ims.example', '["zhang.ming@company.com"]', '[]', '[]', '2026-06-30T16:22:00+09:00', 'The programme team is finalizing room assignments and session times. Do not treat the registration confirmation as the final daily agenda.', NULL, 0, 0, 0, NULL, NULL, '{"category":"conference"}', 6508, 141, '2026-06-30T16:22:00+09:00'),
(1537, 1, '<hotel-security-note-20260623@company.com>', 'Hotel guest information and secure handling', 'security@company.com', '["zhang.ming@company.com"]', '[]', '[]', '2026-06-23T11:09:00+08:00', 'Use accurate guest identity through the approved booking channel. Do not invent lodging details or transmit passport scans through an unapproved mailbox.', NULL, 1, 1, 0, NULL, NULL, '{"category":"security"}', 6537, 165, '2026-06-23T11:09:00+08:00'),
